struct Feedback {
    let tag: String
    let text: String
    var isBlocking: Bool { tag == "BLOCKING" }
}
let f = Feedback(tag: "BLOCKING", text: "Add test case")
print(f.isBlocking ? "Must Fix" : "Optional")

struct PRStats {
    let additions: Int
    let deletions: Int
    var diffSize: Int { additions + deletions }
}
let pr = PRStats(additions: 120, deletions: 30)
print("Diff: \(pr.diffSize)")

